# Отдельно в оболочке:
cmake --list-presets
cmake --preset dev
cmake --build --preset dev

// main.cpp — полная маленькая программа для Windows/MSVC
#include <array>
#include <iostream>
int sum(const std::array<int, 4>& values) {
    int total = 0;
    for (int value : values) total += value;
    return total;
}
int main() {
    const std::array<int, 4> values{2, 4, 6, 8};
    std::cout << sum(values) << '\n';
}
// В Visual Studio: Debug/x64, breakpoint на total += value.
// Открой Locals, Watch и Call Stack; выполни несколько Step Over.

// overflow.cpp — намеренно ошибочный учебный пример
#include <memory>
int main(int argc, char**) {
    auto values = std::make_unique<int[]>(4);
    values[argc + 3] = 7; // без аргументов argc==1, индекс 4 вне [0,4)
    return values[0];
}

