// ub.cpp — намеренно ошибочная арифметика
#include <climits>
int main(int argc, char**) {
    volatile int input = INT_MAX;
    int result = input + argc;
    return result == 0;
}

# Linux GCC или совместимый Clang:
g++ -std=c++20 -g -O1 -fno-omit-frame-pointer -fsanitize=address,undefined ub.cpp -o ub
./ub
# Здесь volatile сохраняет учебное чтение; это не средство синхронизации.

// race.cpp — намеренно ошибочный учебный пример
#include <iostream>
#include <thread>
int counter = 0;
void work() { for (int i = 0; i < 10000; ++i) ++counter; }
int main() {
    std::thread a(work), b(work);
    a.join(); b.join();
    std::cout << counter << '\n';
}

# Linux, отдельная TSan-сборка:
g++ -std=c++20 -g -O1 -fsanitize=thread -pthread race.cpp -o race-tsan
./race-tsan

// leak.cpp — намеренная потеря владения
int* make_value() { return new int(42); }
int main() {
    int* value = make_value();
    int result = *value;
    value = nullptr; // delete не был вызван
    return result == 42 ? 0 : 1;
}

# Linux, самостоятельная сборка без sanitizer:
g++ -g -O0 leak.cpp -o leak
valgrind --tool=memcheck --leak-check=full --show-leak-kinds=all --track-origins=yes ./leak

