// Фрагмент функции для Google Benchmark; не standalone main.
static void BM_sum(benchmark::State& state) {
    std::vector<unsigned> data(4096, 7);
    for (auto _ : state) {
        benchmark::DoNotOptimize(data.data());
        unsigned total = 0;
        for (unsigned value : data) total += value;
        benchmark::DoNotOptimize(total);
    }
}
BENCHMARK(BM_sum);
// Требуются <benchmark/benchmark.h>, <vector>, библиотека benchmark
// и benchmark_main либо собственный BENCHMARK_MAIN().
